package com.gathin.tvhome;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class RecommendationVarietyTest {
 private List<MediaRepository.MediaItem> catalog(int count){List<MediaRepository.MediaItem> result=new ArrayList<>();for(int i=0;i<count;i++)result.add(new MediaRepository.MediaItem("tt"+(9100000+i),"Título "+i,"movie","8","2026","Drama","","","","","",100));return result;}
 private Set<String> ids(List<MediaRepository.MediaItem> list){Set<String> result=new HashSet<>();for(MediaRepository.MediaItem item:list)result.add(item.imdbId);return result;}
 @Test public void neverRepeatsThePreviousScreenWhenFreshTitlesAreScatteredAcrossRanking(){List<MediaRepository.MediaItem> list=catalog(12);Set<String> previous=new HashSet<>();for(int i=0;i<12;i+=2)previous.add(list.get(i).imdbId);for(int seed=0;seed<100;seed++){List<MediaRepository.MediaItem> shuffled=MediaRepository.variedOrder(list,previous,previous,new Random(seed));assertTrue(Collections.disjoint(ids(shuffled.subList(0,4)),previous));assertEquals(ids(list),ids(shuffled));}}
 @Test public void exhaustedRecentHistoryStillAvoidsTheImmediatelyPreviousScreen(){List<MediaRepository.MediaItem> list=catalog(8);Set<String> previous=ids(list.subList(0,4));for(int seed=0;seed<100;seed++){List<MediaRepository.MediaItem> shuffled=MediaRepository.variedOrder(list,ids(list),previous,new Random(seed));assertEquals(ids(list.subList(4,8)),ids(shuffled.subList(0,4)));}}
 @Test public void freshRecommendationsTakePriorityOverOlderAndPreviousTitles(){List<MediaRepository.MediaItem> list=catalog(12);Set<String> recent=ids(list.subList(0,8)),previous=ids(list.subList(0,4));assertEquals(ids(list.subList(8,12)),ids(MediaRepository.variedOrder(list,recent,previous,new Random(8)).subList(0,4)));}
 @Test public void smallCatalogsNeverBecomeEmptyOrRepeatItemsWithinTheList(){for(int count=0;count<=7;count++){List<MediaRepository.MediaItem> list=catalog(count),before=new ArrayList<>(list);List<MediaRepository.MediaItem> shuffled=MediaRepository.variedOrder(list,ids(list),ids(list),new Random(3));assertEquals(count,shuffled.size());assertEquals(count,ids(shuffled).size());assertEquals(before,list);}}
 @Test public void equalInputsProduceDifferentOrdersAndStillFavorStrongerAffinity(){List<MediaRepository.MediaItem> list=catalog(20);Random random=new Random(42);int[] first=new int[20];Set<String> orders=new HashSet<>();for(int i=0;i<5000;i++){List<MediaRepository.MediaItem> result=MediaRepository.variedOrder(list,Collections.emptySet(),Collections.emptySet(),random);first[list.indexOf(result.get(0))]++;orders.add(result.get(0).imdbId+result.get(1).imdbId);}assertTrue(first[0]>first[10]*5);assertTrue(orders.size()>20);}
 @Test public void exposureRoundTripPreservesOrderAndRecencyAcrossColdStarts(){Set<String> restored=MainActivity.recommendationIds("tt9100000,tt9100001,tt9100000,bad,tt9100002",12);assertEquals(Arrays.asList("tt9100001","tt9100000","tt9100002"),new ArrayList<>(restored));assertEquals(restored,MainActivity.recommendationIds(String.join(",",restored),12));assertEquals(new LinkedHashSet<>(Arrays.asList("tt9100000","tt9100002")),MainActivity.recommendationIds(String.join(",",restored),2));assertTrue(MainActivity.recommendationIds(null,4).isEmpty());assertTrue(MainActivity.recommendationIds("tt9100000",0).isEmpty());}
}
